CREATE OR REPLACE FUNCTION public.admin_delete_reward(p_token uuid, p_reward_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  update public.reward_redemptions set reward_id = null where reward_id = p_reward_id;
  update public.points_transactions set reward_id = null where reward_id = p_reward_id;
  delete from public.rewards where id = p_reward_id;
  return jsonb_build_object('ok', true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_login(p_username text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.admin_users; tok uuid;
begin
  select * into a from public.admin_users where username = btrim(p_username);
  if a is null or a.password_hash <> encode(extensions.digest('dose:' || p_password, 'sha256'), 'hex') then
    raise exception 'bad_credentials';
  end if;
  insert into public.admin_sessions (admin_id) values (a.id) returning token into tok;
  return jsonb_build_object('token', tok, 'username', a.username);
end $function$

CREATE OR REPLACE FUNCTION public.admin_publish_promo(p_token uuid, p_code text, p_discount integer, p_scope text DEFAULT 'all'::text, p_target text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cnt int; v_title text; v_body text; v_scope text; target_name text;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  if btrim(p_code) = '' then raise exception 'invalid_code'; end if;
  if p_discount is null or p_discount < 1 or p_discount > 90 then raise exception 'invalid_discount'; end if;
  v_scope := coalesce(p_scope, 'all');
  if v_scope not in ('all','product','category') then raise exception 'invalid_scope'; end if;
  if v_scope = 'product' and p_target is null then raise exception 'invalid_target'; end if;

  insert into public.settings (key, value) values ('promo_code', upper(btrim(p_code)))
  on conflict (key) do update set value = excluded.value;
  insert into public.settings (key, value) values ('promo_discount', p_discount::text)
  on conflict (key) do update set value = excluded.value;
  insert into public.settings (key, value) values ('promo_scope', v_scope)
  on conflict (key) do update set value = excluded.value;
  insert into public.settings (key, value) values ('promo_target', coalesce(p_target,''))
  on conflict (key) do update set value = excluded.value;

  v_scope := coalesce(p_scope,'all');
  if v_scope = 'product' then
    select name_ar into target_name from public.products where id = p_target::int;
    v_body := 'استخدم الكود ' || upper(btrim(p_code)) || ' واحصل على خصم ' || p_discount || '% على ' || coalesce(target_name,'منتج محدد');
  elsif v_scope = 'category' then
    select name_ar into target_name from public.categories where slug = p_target;
    v_body := 'استخدم الكود ' || upper(btrim(p_code)) || ' واحصل على خصم ' || p_discount || '% على كامل فئة ' || coalesce(target_name,'محددة');
  else
    v_body := 'استخدم الكود ' || upper(btrim(p_code)) || ' واحصل على خصم ' || p_discount || '% على طلبك كاملًا';
  end if;
  v_title := '🎁 كود خصم جديد من Dose Cafe';

  insert into public.notifications (customer_id, title, body, kind)
  select c.id, v_title, v_body, 'admin' from public.customers c where c.is_active;
  select count(*) into cnt from public.notifications where kind = 'admin' and title = v_title;

  begin
    perform net.http_post(
      url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer anon'),
      body := jsonb_build_object('all', true, 'title', v_title, 'body', v_body));
  exception when others then null;
  end;

  return jsonb_build_object('ok', true, 'notified', cnt);
end $function$

CREATE OR REPLACE FUNCTION public.admin_sales_summary(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare today date;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  today := (now() at time zone 'Asia/Damascus')::date;
  return jsonb_build_object(
    'today', (select jsonb_build_object('total', coalesce(sum(total_cents),0), 'count', coalesce(sum(orders_count),0)) from public.sales_daily where day = today),
    'week',  (select jsonb_build_object('total', coalesce(sum(total_cents),0), 'count', coalesce(sum(orders_count),0)) from public.sales_daily where day > today - 7),
    'month', (select jsonb_build_object('total', coalesce(sum(total_cents),0), 'count', coalesce(sum(orders_count),0)) from public.sales_daily where day >= date_trunc('month', today)),
    'daily', (select coalesce(jsonb_agg(x order by x.day), '[]'::jsonb) from (
                select day, total_cents, orders_count from public.sales_daily where day > today - 15) x)
  );
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_ad(p_token uuid, p_ad jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id int; v_cat text; v_title text; v_body text;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  v_cat := coalesce(nullif(p_ad->>'category_slug',''), null);
  if v_cat is not null then
    select 'عروض ' || name_ar into v_title from public.categories where slug = v_cat;
    if v_title is null then raise exception 'invalid_category'; end if;
  else
    v_title := coalesce(nullif(p_ad->>'title',''), 'عرض خاص من Dose Cafe');
  end if;

  if (p_ad->>'id')::int > 0 then
    update public.advertisements set
      image_url = coalesce(p_ad->>'image_url',''), title = v_title,
      description_ar = coalesce(p_ad->>'description_ar',''),
      category_slug = v_cat,
      old_price_cents = null, new_price_cents = null, discount_percent = null,
      ends_at = nullif(p_ad->>'ends_at','')::timestamptz,
      is_active = coalesce((p_ad->>'is_active')::boolean, true),
      full_screen = coalesce((p_ad->>'full_screen')::boolean, false)
    where id = (p_ad->>'id')::int;
    return jsonb_build_object('ok', true, 'new', false);
  end if;

  insert into public.advertisements (image_url, title, description_ar, category_slug, old_price_cents, new_price_cents, discount_percent, starts_at, ends_at, is_active, full_screen, show_in_hero)
  values (coalesce(p_ad->>'image_url',''), v_title, coalesce(p_ad->>'description_ar',''),
          v_cat, null, null, null,
          now(), nullif(p_ad->>'ends_at','')::timestamptz,
          coalesce((p_ad->>'is_active')::boolean,true), coalesce((p_ad->>'full_screen')::boolean,false),
          coalesce((p_ad->>'show_in_hero')::boolean, true))
  returning id into new_id;

  -- إشعار داخلي وخارجي لكل الزبائن بأسلوب الفئة
  if v_cat is not null then
    select name_ar into v_body from public.categories where slug = v_cat;
    v_title := '📣 عروض جديدة على ' || v_body;
    v_body := coalesce(nullif(p_ad->>'description_ar',''), 'عروض خاصة على ' || v_body) || ' — اطلبها الآن من Dose Cafe!';
    insert into public.notifications (customer_id, title, body, kind)
    select c.id, v_title, v_body, 'admin' from public.customers c where c.is_active;
    begin
      perform net.http_post(
        url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
        headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer anon'),
        body := jsonb_build_object('all', true, 'title', v_title, 'body', v_body));
    exception when others then null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'new', true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_addition(p_token uuid, p_addition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare aid int; pid int;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  if btrim(coalesce(p_addition->>'name_ar','')) = '' then raise exception 'invalid_name'; end if;
  if (p_addition->>'id')::int > 0 then
    update public.additions set
      name_ar = btrim(p_addition->>'name_ar'),
      price_cents = greatest(0, coalesce((p_addition->>'price_cents')::int, 0)),
      is_active = coalesce((p_addition->>'is_active')::boolean, true)
    where id = (p_addition->>'id')::int
    returning id into aid;
    if aid is null then raise exception 'not_found'; end if;
    delete from public.addition_products where addition_id = aid;
  else
    insert into public.additions (name_ar, price_cents, is_active)
    values (btrim(p_addition->>'name_ar'), greatest(0, coalesce((p_addition->>'price_cents')::int, 0)),
            coalesce((p_addition->>'is_active')::boolean, true))
    returning id into aid;
  end if;
  for pid in select j::int from jsonb_array_elements_text(coalesce(p_addition->'product_ids', '[]'::jsonb)) j loop
    insert into public.addition_products (addition_id, product_id) values (aid, pid)
    on conflict do nothing;
  end loop;
  return jsonb_build_object('ok', true, 'id', aid);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_settings(p_token uuid, p_settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text; v text;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  for k, v in select * from jsonb_each_text(p_settings) loop
    insert into public.settings (key, value) values (k, v)
    on conflict (key) do update set value = excluded.value;
  end loop;
  return jsonb_build_object('ok', true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_send_notification(p_token uuid, p_title text, p_body text DEFAULT ''::text, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cnt int := 0;
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  if btrim(p_title) = '' then raise exception 'invalid_title'; end if;

  insert into public.notifications (customer_id, title, body, kind)
  select coalesce(p_customer_id, c.id), btrim(p_title), coalesce(p_body, ''), 'admin'
  from public.customers c
  where c.is_active and (p_customer_id is null or c.id = p_customer_id);
  get diagnostics v_cnt = row_count;

  -- إشعار خارجي فوري للأجهزة (كل الزبائن أو العميل المحدد)
  begin
    perform net.http_post(
      url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer anon'),
      body := case
        when p_customer_id is null
          then jsonb_build_object('all', true, 'title', btrim(p_title), 'body', coalesce(p_body, ''))
          else jsonb_build_object('customer_id', p_customer_id, 'title', btrim(p_title), 'body', coalesce(p_body, ''))
      end);
  exception when others then null;
  end;

  return v_cnt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_order_status(p_token uuid, p_order_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

declare
  o public.orders; bal integer; was_completed boolean;
  titles jsonb := jsonb_build_object(
    'confirmed','✅ تم تأكيد طلبك','preparing','👨‍🍳 طلبك قيد التحضير',
    'ready','☕ طلبك جاهز','out_for_delivery','🛵 طلبك في الطريق إليك!','completed','✅ تم إكمال طلبك','cancelled','❌ تم إلغاء طلبك');
begin
  if not public._valid_admin(p_token) then raise exception 'unauthorized'; end if;
  if p_status not in ('pending','confirmed','preparing','ready','out_for_delivery','completed','cancelled') then raise exception 'invalid_status'; end if;
  select * into o from public.orders where id = p_order_id;
  if o is null then raise exception 'not_found'; end if;
  if o.status = p_status then return jsonb_build_object('ok', true); end if;

  update public.orders set status = p_status where id = o.id returning * into o;

  was_completed := o.completed_at is not null;
  if p_status in ('completed','cancelled') and o.completed_at is null then
    update public.orders set completed_at = now() where id = o.id returning * into o;
  end if;
  if p_status = 'completed' and not was_completed then
    perform public._record_sales(o.id, true);
  elsif p_status = 'cancelled' and was_completed then
    perform public._record_sales(o.id, false);
  end if;

  if p_status = 'completed' and not o.points_awarded then
    perform public._award_points(o.customer_id, o.total_points, o.id, 'order#' || o.order_number);
    update public.orders set points_awarded = true where id = o.id;
    select points into bal from public.customers where id = o.customer_id;
    perform public._notify(o.customer_id, '✅ تم إكمال طلبك',
      '⭐ حصلت على ' || o.total_points || ' نقطة — رصيدك الحالي: ' || bal || ' نقطة', 'order');
    begin
      perform net.http_post(
        url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
        headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer anon'),
        body := jsonb_build_object('customer_id', o.customer_id, 'title', '✅ تم إكمال طلبك',
          'body', '⭐ حصلت على ' || o.total_points || ' نقطة — رصيدك الحالي: ' || bal || ' نقطة'));
    exception when others then null;
    end;
  elsif p_status = 'cancelled' and o.points_awarded then
    perform public._award_points(o.customer_id, -o.total_points, o.id, 'cancel#' || o.order_number);
    update public.orders set points_awarded = false where id = o.id;
    perform public._notify(o.customer_id, '❌ تم إلغاء طلبك', 'طلب رقم #' || o.order_number, 'order');
    begin
      perform net.http_post(
        url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
        headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer anon'),
        body := jsonb_build_object('customer_id', o.customer_id, 'title', '❌ تم إلغاء طلبك', 'body', 'طلب رقم #' || o.order_number));
    exception when others then null;
    end;
  elsif titles ? p_status then
    perform public._notify(o.customer_id, titles->>p_status, 'طلب رقم #' || o.order_number, 'order');
    begin
      perform net.http_post(
        url := 'https://mqstsxuscqbxnyejhixk.supabase.co/functions/v1/push',
        headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer anon'),
        body := jsonb_build_object('customer_id', o.customer_id, 'title', titles->>p_status, 'body', 'طلب رقم #' || o.order_number));
    exception when others then null;
    end;
  end if;

  return jsonb_build_object('ok', true);
end 
$function$

CREATE OR REPLACE FUNCTION public.admin_set_order_status(p_token uuid, p_order_id uuid, p_status text, p_eta_minutes integer DEFAULT NULL::integer)
